const byslug = new Map(L.map((l) => [l.slug, l]));
const range = (t: string) => (t.match(/\d+ tot \d+ minuten/) || ['20 tot 30 minuten'])[0];

function make(l: Loc): Page {
  const where = `in ${l.name}`;
  const eta = range(l.time);
  const stad = l.kind === 'stad';
  const plaats = l.kind === 'plaats';
  const nearPages = l.near.map((s) => byslug.get(s)!).filter(Boolean);
  const spotTxt = l.spots.join(', ');

  const faq: Faq[] = [
    { q: `Hoe snel bezorgen jullie ${where}?`, a: `${l.time} Je betaalt bij aflevering met PIN of contant.` },
    l.q,
    ...l.extraQ,
    {
      q: `Welke Fastgas tanks kan ik ${where} bestellen?`,
      a: 'We bezorgen de Fastgas Wegwerp Tank in 2KG (2000 gram), 4KG (4000 gram) en 10KG (10.000 gram), verzegeld en met een label met serienummer, inhoud en keuringsgegevens. Er is geen statiegeld. Een overzicht staat op [alle lachgas tanks](/lachgas-tanks/).',
    },
    {
      q: `Is er een minimumleeftijd ${where}?`,
      a: `Ja, ook ${where} leveren we uitsluitend aan klanten van ${site.minAge} jaar en ouder en uitsluitend voor toegestaan gebruik, zoals keuken, horeca, catering of technische toepassingen. De koerier kan om legitimatie vragen en levert niet bij twijfel. Lees [wat de Opiumwet zegt](/is-lachgas-verboden/).`,
    },
  ];

  const blocks: Block[] = [
    { t: 'h2', x: stad ? 'Lachgas bezorgen in heel Amsterdam' : plaats ? `Lachgas laten bezorgen ${where}` : `Lachgas bezorgen ${where}` },
    { t: 'p', x: l.character },
    { t: 'p', x: l.detail },
    { t: 'p', x: l.access },
  ];

  if (stad) {
    blocks.push(
      { t: 'h2', x: 'Alle stadsdelen en Weesp' },
      { t: 'table', head: ['Stadsdeel', 'Wat je moet weten'], rows: l.notes },
      { t: 'p', x: `Bekende oriëntatiepunten in de stad zijn ${spotTxt}. Zit je ergens anders, stuur dan je adres; dan zeggen we direct of en hoe snel we er kunnen zijn.` },
    );
  } else if (plaats) {
    blocks.push(
      { t: 'h2', x: `Wijken en kernen ${where}` },
      { t: 'ul', x: l.notes.map(([w, r]) => `**${w}**: ${r}`) },
      { t: 'p', x: `Bekende plekken ${where} zijn ${spotTxt}. Staat jouw buurt er niet bij, stuur gerust je adres, dan zeggen we direct of we er kunnen komen.` },
    );
  } else {
    blocks.push(
      { t: 'h2', x: `Wijken ${where}` },
      { t: 'table', head: ['Wijk', 'Waar je op moet letten'], rows: l.notes },
      { t: 'p', x: `Bekende plekken ${where} zijn ${spotTxt}. Staat jouw buurt er niet bij, stuur gerust je adres, dan zeggen we direct of we er kunnen komen.` },
    );
  }

  blocks.push(
    { t: 'h2', x: l.usesH ?? (stad ? 'Voor wie bezorgen we in Amsterdam?' : `Voor wie bezorgen we ${where}?`) },
    { t: 'p', x: l.uses },
    { t: 'p', x: l.size },
    { t: 'h2', x: l.routesH ?? (plaats ? `Bereikbaarheid ${where} vanaf Amsterdam` : stad ? 'Routes en bereikbaarheid in de stad' : `Routes en bereikbaarheid ${where}`) },
    { t: 'p', x: l.routes },
    { t: 'h2', x: l.tipsH ?? `Tips voor een snelle levering ${where}` },
    { t: 'ul', x: l.tips },
    { t: 'h2', x: 'Zo bestel je' },
    {
      t: 'steps',
      x: [
        ['Stuur een WhatsApp of bel', `Geef je adres ${where}, je gewenste formaat (2KG, 4KG of 10KG) en wat voor gebruik het is.`],
        ['Wij bevestigen prijs en tijd', `Verwachte aankomst: ${eta}. We noemen vooraf de prijs; er zijn geen verrassingen achteraf.`],
        ['Betaal bij aflevering', 'Betalen kan met PIN of contant. Een account of vooruitbetaling is niet nodig.'],
      ],
    },
    { t: 'p', x: 'Meer weten voordat je bestelt? Lees [hoe bestellen werkt](/bestellen/), bekijk het [volledige bezorggebied](/bezorggebied/) of de [veelgestelde vragen](/veelgestelde-vragen/). Over de regels rond lachgas lees je op [is lachgas verboden](/is-lachgas-verboden/) en [veilig gebruik](/veilig-gebruik-lachgas/).' },
    { t: 'note', x: `Levering uitsluitend aan ${site.minAge}+ en uitsluitend voor toegestane toepassingen, zoals keuken, horeca en technisch gebruik. Bij twijfel over het beoogde gebruik leveren we niet.` },
    { t: 'h2', x: `Ook in de buurt van ${l.name}` },
    {
      t: 'cards',
      x: nearPages.map((n) => ({ h: `Lachgas ${n.name}`, p: n.intro.split('. ')[0] + '.', href: `/${n.slug}/` })),
    },
  );

  return {
    slug: l.slug,
    group: 'location',
    kind: 'location',
    place: l.name,
    nav: l.name,
    parent: 'bezorggebied',
    title: l.title ?? `Lachgas bezorgen in ${l.name}`,
    desc: l.desc,
    h1: `Lachgas ${l.name}`,
    kicker: plaats ? `Bezorggebied ${l.region}` : stad ? 'Heel Amsterdam' : 'Stadsdeel van Amsterdam',
    lead: `${l.intro} Wij bezorgen de Fastgas Wegwerp Tank ${where}, dag en nacht.`,
    blocks,
    faq,
    related: ['lachgas-tanks', 'bestellen', 'bezorggebied', 'lachgas-24-7', 'lachgas-horeca', stad || !plaats ? 'lachgas-evenementen' : 'lachgas-bezorgen'],
  };
}

export const locations: Page[] = L.map(make);
export const locationData = L;
